#!/bin/bash
# calc.sh — интерактивный калькулятор (уровень 8, аналог calc.ps1)
# Операции: + - * / % ^ (степень) root (корень n-й степени) sin cos tan log ln

show_help() {
    cat <<'EOF'
=== КАЛЬКУЛЯТОР ===
Бинарные:  <число> <оп> <число>   где op = + - * / % ^ root
Унарные:   <функция> <число>       где функция = sin cos tan log ln sqrt
Примеры:   2 + 3     |  2 ^ 10   |  27 root 3   |  sin 1.57   |  sqrt 16
Выход:     q
EOF
}

calc_unary() {
    local fn=$1 x=$2
    case $fn in
        sqrt) awk -v x="$x" 'BEGIN {print sqrt(x)}' ;;
        sin)  awk -v x="$x" 'BEGIN {print sin(x)}' ;;
        cos)  awk -v x="$x" 'BEGIN {print cos(x)}' ;;
        tan)  awk -v x="$x" 'BEGIN {print tan(x)}' ;;
        log)  awk -v x="$x" 'BEGIN { if (x<=0) exit 1; print log(x)/log(10) }' ;;
        ln)   awk -v x="$x" 'BEGIN { if (x<=0) exit 1; print log(x) }' ;;
        *) return 2 ;;
    esac
}

calc_binary() {
    local a=$1 op=$2 b=$3
    case $op in
        +) awk -v a="$a" -v b="$b" 'BEGIN {print a+b}' ;;
        -) awk -v a="$a" -v b="$b" 'BEGIN {print a-b}' ;;
        '*') awk -v a="$a" -v b="$b" 'BEGIN {print a*b}' ;;
        /) awk -v a="$a" -v b="$b" 'BEGIN { if (b==0) exit 1; print a/b }' ;;
        %) awk -v a="$a" -v b="$b" 'BEGIN { if (b==0) exit 1; printf "%.10g\n", (a-int(a/b)*b) }' ;;
        ^) awk -v a="$a" -v b="$b" 'BEGIN {print a^b}' ;;
        root) awk -v a="$a" -v b="$b" 'BEGIN { if (b==0) exit 1; print a^(1/b) }' ;;
        *) return 2 ;;
    esac
}

is_number() {
    [[ $1 =~ ^-?[0-9]+(\.[0-9]+)?$ ]]
}

while true; do
    show_help
    read -r -p "Введите выражение: " line
    line=$(echo "$line" | tr 'A-Z' 'a-z')

    [[ -z $line ]] && continue
    [[ $line == "q" || $line == "выход" ]] && break

    read -r -a parts <<< "$line"

    if [[ ${#parts[@]} -eq 3 ]]; then
        if ! is_number "${parts[0]}" || ! is_number "${parts[2]}"; then
            echo "Ошибка: неверный ввод числа"; continue
        fi
        if [[ "${parts[1]}" == "/" || "${parts[1]}" == "%" || "${parts[1]}" == "root" ]] \
           && awk -v b="${parts[2]}" 'BEGIN {exit !(b==0)}'; then
            echo "Ошибка: деление на ноль"; continue
        fi
        result=$(calc_binary "${parts[0]}" "${parts[1]}" "${parts[2]}") \
            || { echo "Ошибка: недопустимая операция или деление на ноль"; continue; }
        printf "Результат: %s\n" "$result"

    elif [[ ${#parts[@]} -eq 2 ]]; then
        if ! is_number "${parts[1]}"; then
            echo "Ошибка: неверный ввод числа"; continue
        fi
        case ${parts[0]} in
            log|ln)
                if awk -v x="${parts[1]}" 'BEGIN {exit !(x<=0)}'; then
                    echo "Ошибка: аргумент логарифма должен быть > 0"; continue
                fi
                ;;
        esac
        result=$(calc_unary "${parts[0]}" "${parts[1]}") \
            || { echo "Ошибка: неизвестная функция"; continue; }
        printf "Результат: %s\n" "$result"
    else
        echo "Ошибка: неверный формат ввода"
    fi
done

echo "Калькулятор завершён."

# calc.ps1 - калькулятор (уровень 8, PowerShell)
# Поддерживаемые операции: + - * /, остаток %, степень ^,
# корень sqrt a и root a b, sin cos tan (градусы),
# десятичный log10 и натуральный ln.
#
# Разбор выражения идёт по правилам приоритета: сначала ^ ,
# затем * / % , затем + - . Один общий шаблон на всё выражение
# не работал: он не разбирал 2+3*4 и путал номер группы
# named-capture с номером оператора, из-за чего 10/0 падал
# с ошибкой преобразования типа.
# Выражения передаются обычными аргументами ($args), а не через параметр
# с ValueFromRemainingArguments: такой параметр перехватывал и сам путь,
# из-за чего calc.ps1 2+3*4 пытался читать файл с именем "2+3*4".
# -FileIn - файл с выражениями, по одному в строке. Нужен для автоматического
# прогона: Read-Host игнорирует перенаправленный stdin и блокируется.

$ErrorActionPreference = "Continue"

# Файл ввода читаем байтами и декодируем кодовой страницей консоли:
# Get-Content без -Encoding берёт ANSI и ломает кириллицу (866 против 1251).
function Get-ConsoleLines([string]$path) {
    $enc = [System.Text.Encoding]::GetEncoding([int][Console]::OutputEncoding.CodePage)
    $text = $enc.GetString([System.IO.File]::ReadAllBytes($path))
    foreach ($l in ($text -split "`r?`n")) {
        if ($l.Trim() -eq "") { continue }
        $l.Trim()
    }
}

function Show-Help {
    Write-Host "=== Калькулятор: поддерживаемые операции ==="
    Write-Host "  a+b, a-b, a*b, a/b        базовая арифметика"
    Write-Host "  a%b                      остаток от деления"
    Write-Host "  a^b                      возведение в степень"
    Write-Host "  root a b                 корень b-й степени из a"
    Write-Host "  sin a, cos a, tan a      тригонометрия (градусы)"
    Write-Host "  log10 a, ln a            десятичный и натуральный логарифмы"
    Write-Host "  sqrt a                   квадратный корень"
    Write-Host ""
    Write-Host "  Примеры: 2+3*4   root 27 3   sin 30   log10 100   10%3"
}

# Базовое число с необязательным знаком. Культура фиксирована,
# иначе на машине с запятой в качестве разделителя Parse бросает исключение.
function Get-Number([string]$t) {
    $t = $t.Trim()
    if ($t -notmatch '^[+-]?[0-9]+(\.[0-9]+)?$') { return $null }
    return [double]::Parse($t, [Globalization.CultureInfo]::InvariantCulture)
}

# Ошибку передаём через скриптовую переменную, а не через throw:
# throw прервал бы весь пакет и следующие выражения не считались бы.
$script:Err = $null

# Уровень 1: сложение и вычитание - низший приоритет, левоассоциативно.
function Eval-Sum([string]$e) {
    $m = [regex]::Match($e, '^(.+?)\s*([+-])\s*(.+)$')
    if ($m.Success -and $m.Groups[1].Value -match '[0-9)]') {
        $l = Eval-Product $m.Groups[1].Value
        if ($null -eq $l) { return $null }
        $r = Eval-Product $m.Groups[3].Value
        if ($null -eq $r) { return $null }
        if ($m.Groups[2].Value -eq '+') { return $l + $r }
        return $l - $r
    }
    return Eval-Product $e
}

# Уровень 2: умножение, деление, остаток от деления.
function Eval-Product([string]$e) {
    $m = [regex]::Match($e, '^(.+?)\s*([*/%])\s*(.+)$')
    if ($m.Success -and $m.Groups[1].Value -match '[0-9)]') {
        $l = Eval-Power $m.Groups[1].Value
        if ($null -eq $l) { return $null }
        $r = Eval-Power $m.Groups[3].Value
        if ($null -eq $r) { return $null }
        switch ($m.Groups[2].Value) {
            "*" { return $l * $r }
            "/" {
                if ($r -eq 0) { $script:Err = "деление на ноль невозможно"; return $null }
                return $l / $r
            }
            default {
                if ($r -eq 0) { $script:Err = "остаток от деления на ноль невозможен"; return $null }
                return $l - [math]::Floor($l / $r) * $r
            }
        }
    }
    return Eval-Power $e
}

# Уровень 3: возведение в степень - правоассоциативно.
function Eval-Power([string]$e) {
    $m = [regex]::Match($e, '^(.+?)\s*\^\s*(.+)$')
    if ($m.Success) {
        $l = Get-Number $m.Groups[1].Value
        if ($null -eq $l) { return $null }
        $r = Eval-Power $m.Groups[2].Value
        if ($null -eq $r) { return $null }
        return [math]::Pow($l, $r)
    }
    return Get-Number $e
}

# Форматирование числа: запятая как десятичный разделитель ломает
# последующий разбор выражения, поэтому печатаем точкой.
function Fmt([double]$v) {
    # Печатаем точкой (инвариантная культура), без хвостовых нулей:
    # запятая сломала бы последующий разбор выражения, а нули не нужны.
    $s = $v.ToString("F10", [System.Globalization.CultureInfo]::InvariantCulture)
    if ($s.Contains(".")) { $s = $s.TrimEnd("0").TrimEnd(".") }
    return $s
}

function Invoke-Calc([string]$line) {
    $e = $line.Trim()
    if ($e -eq "") { return }
    $script:Err = $null

    if ($e -match '^\s*root\s+(\S+)\s+(\S+)\s*$') {
        $a = Get-Number $matches[1]; $n = Get-Number $matches[2]
        if ($null -eq $a -or $null -eq $n) { Write-Host "ОШИБКА: не удалось разобрать выражение: $e" -ForegroundColor Red; return }
        if ($n -eq 0) { Write-Host "ОШИБКА: показатель корня не может быть нулём" -ForegroundColor Red; return }
        Write-Host ("{0} = {1}" -f $e, ((Fmt ([math]::Pow($a, 1.0 / $n)))))
        return
    }
    if ($e -match '^\s*(sin|cos|tan)\s+(\S+)\s*$') {
        $fn = $matches[1]; $deg = Get-Number $matches[2]
        if ($null -eq $deg) { Write-Host "ОШИБКА: не удалось разобрать выражение: $e" -ForegroundColor Red; return }
        $rad = $deg * [math]::PI / 180
        $v = switch ($fn) {
            "sin" { [math]::Sin($rad) }
            "cos" { [math]::Cos($rad) }
            "tan" { [math]::Tan($rad) }
        }
        Write-Host ("{0} = {1}" -f $e, (Fmt $v))
        return
    }
    if ($e -match '^\s*log10\s+(\S+)\s*$') {
        $a = Get-Number $matches[1]
        if ($null -eq $a) { Write-Host "ОШИБКА: не удалось разобрать выражение: $e" -ForegroundColor Red; return }
        if ($a -le 0) { Write-Host "ОШИБКА: аргумент логарифма должен быть больше нуля" -ForegroundColor Red; return }
        Write-Host ("{0} = {1}" -f $e, ((Fmt ([math]::Log10($a)))))
        return
    }
    if ($e -match '^\s*ln\s+(\S+)\s*$') {
        $a = Get-Number $matches[1]
        if ($null -eq $a) { Write-Host "ОШИБКА: не удалось разобрать выражение: $e" -ForegroundColor Red; return }
        if ($a -le 0) { Write-Host "ОШИБКА: аргумент логарифма должен быть больше нуля" -ForegroundColor Red; return }
        Write-Host ("{0} = {1}" -f $e, ((Fmt ([math]::Log($a)))))
        return
    }
    if ($e -match '^\s*sqrt\s+(\S+)\s*$') {
        $a = Get-Number $matches[1]
        if ($null -eq $a) { Write-Host "ОШИБКА: не удалось разобрать выражение: $e" -ForegroundColor Red; return }
        if ($a -lt 0) { Write-Host "ОШИБКА: подкоренное выражение не может быть отрицательным" -ForegroundColor Red; return }
        Write-Host ("{0} = {1}" -f $e, ((Fmt ([math]::Sqrt($a)))))
        return
    }

    $v = Eval-Sum $e
    if ($script:Err) {
        Write-Host ("ОШИБКА: {0} ({1})" -f $script:Err, $e) -ForegroundColor Red
    } elseif ($null -eq $v) {
        Write-Host "ОШИБКА: не удалось разобрать выражение: $e" -ForegroundColor Red
    } else {
        Write-Host ("{0} = {1}" -f $e, (Fmt $v))
    }
}

Write-Host "=== Калькулятор ==="
Show-Help

# Разбор аргументов вручную: объявленный параметр [string]$FileIn
# получал первый позиционный аргумент, и "calc.ps1 2+3*4" пытался
# прочитать файл с именем "2+3*4".
# Ключ -Help печатает справку и завершает работу: без него запуск без
# аргументов уходил в интерактивный режим и намертво блокировал драйвер.
$FileIn = $null
$WantHelp = $false
$Exprs = @()
for ($i = 0; $i -lt $args.Count; $i++) {
    if ($args[$i] -eq '-FileIn') {
        $i++
        if ($i -lt $args.Count) { $FileIn = $args[$i] }
    } elseif ($args[$i] -eq '-Help') {
        $WantHelp = $true
    } else {
        $Exprs += $args[$i]
    }
}

if ($WantHelp) {
    Write-Host ""
    Write-Host "--- Справка по ключам ---"
    Write-Host "  -Help        показать эту справку и выйти"
    Write-Host "  -FileIn путь читать выражения из файла, по одному в строке"
    Write-Host "  выражения    например: calc.ps1 2+3*4 sqrt 16"
    exit 0
}

if ($FileIn) {
    Write-Host ""
    Write-Host "--- Режим ввода из файла: $FileIn ---"
    foreach ($line in (Get-ConsoleLines $FileIn)) {
        if ($line -match '^(выход|exit|quit)$') { break }
        Invoke-Calc $line
    }
} elseif ($Exprs.Count -eq 0) {
    Write-Host ""
    Write-Host "--- Интерактивный режим, для выхода введите выход ---"
    while ($true) {
        $line = Read-Host "calc>"
        if ($line -match '^(выход|exit|quit)$') { Write-Host "Работа завершена."; break }
        Invoke-Calc $line
    }
} else {
    Write-Host ""
    # "sqrt 16" из командной строки приходит двумя аргументами,
    # поэтому склеиваем функцию с её операндом в одно выражение.
    $joined = @()
    for ($i = 0; $i -lt $Exprs.Count; $i++) {
        if ($Exprs[$i] -match '^(root|sin|cos|tan|log10|ln|sqrt)$' -and
            $i + 1 -lt $Exprs.Count) {
            $pair = $Exprs[$i] + ' ' + $Exprs[$i + 1]
            $joined += $pair
            $i++
            if ($Exprs[$i] -ne '' -and $Exprs[$i] -notmatch '^[0-9.+-]' -and
                $i + 1 -lt $Exprs.Count -and $pair -match '^root ') {
                $joined[-1] = $pair + ' ' + $Exprs[$i + 1]
                $i++
            }
        } else {
            $joined += $Exprs[$i]
        }
    }
    foreach ($e in $joined) { Invoke-Calc $e }
}

# tempconv.ps1 - конвертер температур (уровень 8, PowerShell)
# Перевод между Кельвином, Цельсием и Фаренгейтом.
# Исходная единица определяется по суффиксу: 100K, 100C или 100F.
# Файл с исходными значениями, по одному в строке. Нужен для автоматического
# прогона: Read-Host игнорирует перенаправленный stdin и блокируется.
#
# Ключ -FileIn разбирается вручную из $args, а не объявляется параметром:
# объявленный [string]$FileIn является позиционным и первым же значением
# (100K, 100C, ...) перехватывался как путь к файлу - скрипт падал с
# FileNotFoundException вместо convertsения температур.

$FileIn = $null
$values = @()
if ($args.Count -gt 0 -and $args[0] -eq "-FileIn") {
    $FileIn = $args[1]
    if ($args.Count -gt 2) { $values = $args[2..($args.Count - 1)] }
} else {
    $values = $args
}

# Файл ввода читаем байтами и декодируем кодовой страницей консоли:
# Get-Content без -Encoding берёт ANSI и ломает кириллицу (866 против 1251).
function Get-ConsoleLines([string]$path) {
    $enc = [System.Text.Encoding]::GetEncoding([int][Console]::OutputEncoding.CodePage)
    $text = $enc.GetString([System.IO.File]::ReadAllBytes($path))
    foreach ($l in ($text -split "`r?`n")) {
        if ($l.Trim() -eq "") { continue }
        $l.Trim()
    }
}

function To-Kelvin([double]$v, [string]$unit) {
    switch ($unit.ToUpper()) {
        "K" { return $v }
        "C" { return $v + 273.15 }
        "F" { return ($v - 32) * 5 / 9 + 273.15 }
        default { return $null }
    }
}
function From-Kelvin([double]$k, [string]$unit) {
    switch ($unit.ToUpper()) {
        "K" { return $k }
        "C" { return $k - 273.15 }
        "F" { return ($k - 273.15) * 9 / 5 + 32 }
        default { return $null }
    }
}

function Convert-Value([string]$arg) {
    if ($arg -notmatch '^\s*(-?\d+(?:\.\d+)?)\s*([KCF])\s*$') {
        Write-Host "ОШИБКА: неверный ввод: '$arg'. Ожидается число и суффикс K, C или F" -ForegroundColor Red
        return
    }
    $num = [double]$matches[1]
    $unit = $matches[2]
    $k = To-Kelvin $num $unit
    if ($null -eq $k) { Write-Host "ОШИБКА: неизвестная единица $unit" -ForegroundColor Red; return }
    Write-Host ("{0}{1} = {2:N2} K = {3:N2} C = {4:N2} F" -f $num, $unit.ToUpper(), $k,
        (From-Kelvin $k "C"), (From-Kelvin $k "F"))
}

Write-Host "=== Конвертер температур ==="
Write-Host "Поддерживаемые единицы: K (Кельвин), C (Цельсий), F (Фаренгейт)"
Write-Host "Формат ввода: 100K, 100C или 100F"
Write-Host ""

if ($FileIn) {
    # Режим ввода из файла: Read-Host игнорирует перенаправленный stdin,
    # поэтому для автоматического прогона источник входа задаётся явно.
    Write-Host "--- Режим ввода из файла: $FileIn ---"
    foreach ($line in (Get-ConsoleLines $FileIn)) {
        if ($line -match '^(выход|exit|quit)$') { break }
        Convert-Value $line
    }
} elseif ($values.Count -eq 0) {
    Write-Host "--- Интерактивный режим, для выхода введите выход ---"
    while ($true) {
        $line = Read-Host "temp>"
        if ($line -match '^(выход|exit|quit)$') { Write-Host "Работа завершена."; break }
        Convert-Value $line
    }
} else {
    foreach ($v in $values) { Convert-Value $v }
}

# path_count.ps1 - подсчёт исполняемых и неисполняемых команд в PATH (уровень 8)
$ErrorActionPreference = "SilentlyContinue"

Write-Host "============================================================"
Write-Host " СТАТИСТИКА ПО КАТАЛОГАМ PATH"
Write-Host "============================================================"

$env:PATH -split ';' | Where-Object { $_ -ne '' } | ForEach-Object {
    $dir = $_
    if (Test-Path $dir) {
        $items = @(Get-ChildItem -Path $dir -File)
        $exec = @($items | Where-Object { $_.Extension -match '^\.(exe|com|bat|cmd|ps1)$' })
        $nonexec = $items.Count - $exec.Count
        $total = $items.Count
        $pct = if ($total -gt 0) { [math]::Round(100.0 * $exec.Count / $total, 1) } else { 0 }
        "{0,-52} {1,8} {2,8} {3,6}%" -f $dir, $exec.Count, $nonexec, $pct
    } else {
        "{0,-52} {1,8}" -f $dir, "нет такого каталога"
    }
}

Write-Host ""
Write-Host "============================================================"
Write-Host(" ИТОГО ПО PATH")
Write-Host "============================================================"

$allexec = 0; $allnonexec = 0; $found = 0
$env:PATH -split ';' | Where-Object { $_ -ne '' } | ForEach-Object {
    if (Test-Path $_) {
        $found++
        $items = @(Get-ChildItem -Path $_ -File)
        $allexec += @($items | Where-Object { $_.Extension -match '^\.(exe|com|bat|cmd|ps1)$' }).Count
        $allnonexec += @($items | Where-Object { $_.Extension -notmatch '^\.(exe|com|bat|cmd|ps1)$' }).Count
    }
}
Write-Host "Каталогов в PATH:        $found"
Write-Host "Исполняемых команд:      $allexec"
Write-Host "Неисполняемых файлов:    $allnonexec"
Write-Host "Всего файлов:            $($allexec + $allnonexec)"
if (($allexec + $allnonexec) -gt 0) {
    $share = [math]::Round(100.0 * $allexec / ($allexec + $allnonexec), 1)
    Write-Host "Доля исполняемых:        $share%"
}

# tree_sizes.ps1 - вывод дерева каталогов с размерами файлов (уровень 8)
# Для каталогов - количество файлов внутри, для файлов - размер
# в KB/MB/GB (десятичные) и в KiB/MiB/GiB (двоичные).
param([string]$Path = ".")

$ErrorActionPreference = "SilentlyContinue"

function Format-Decimal($bytes) {
    if ($bytes -ge 1GB) { return "{0:N2} GB" -f ($bytes / 1GB) }
    if ($bytes -ge 1MB) { return "{0:N2} MB" -f ($bytes / 1MB) }
    if ($bytes -ge 1KB) { return "{0:N2} KB" -f ($bytes / 1KB) }
    return "$bytes B"
}

function Format-Binary($bytes) {
    if ($bytes -ge 1GB) { return "{0:N2} GiB" -f ($bytes / 1GB) }
    if ($bytes -ge 1MB) { return "{0:N2} MiB" -f ($bytes / 1MB) }
    if ($bytes -ge 1KB) { return "{0:N2} KiB" -f ($bytes / 1KB) }
    return "$bytes B"
}

Write-Host ""
Write-Host "============================================================"
Write-Host " ДЕРЕВО КАТАЛОГОВ: $Path"
Write-Host " Формат размера файла: <десятичные> / <двоичные>"
Write-Host "============================================================"

$items = @(Get-ChildItem -Path $Path -Recurse | Sort-Object { $_.FullName })
Write-Host "[DIR ] $($Path.PadRight(45)) размер: $(Format-Decimal 0) / $(Format-Binary 0)"

foreach ($i in $items) {
    $rel = $i.FullName.Replace((Get-Location).Path, ".")
    if ($i.PSIsContainer) {
        $count = @(Get-ChildItem -Path $i.FullName -File -Recurse).Count
        Write-Host ("[DIR ] {0,-45} файлов: {1}, размер: {2} / {3}" -f $rel.PadRight(45), $count, (Format-Decimal 0), (Format-Binary 0))
    } else {
        Write-Host ("[FILE] {0,-45} {1} / {2}" -f $rel.PadRight(45), (Format-Decimal $i.Length).PadLeft(12), (Format-Binary $i.Length).PadLeft(12))
    }
}
Write-Host "============================================================"

# top5.ps1 - монитор топ-5 процессов по загрузке процессора и памяти (уровень 9)
# Параметр -Interval задаёт период обновления в секундах (по умолчанию 5),
# -Count - сколько кадров вывести (0 = бесконечно, до Ctrl+C).
#
# Clear-Host при перенаправлении вывода очищает уже записанный буфер,
# поэтому в режиме с файлом вывода (-Count > 0) очистки нет: иначе каждый
# кадр, кроме последнего, просто исчезает из вывода.
param(
    [int]$Interval = 5,
    [int]$Count = 0
)

if ($Interval -le 0) {
    Write-Host "Ошибка: интервал должен быть положительным целым числом секунд" -ForegroundColor Red
    exit 1
}

function Format-Dep {
    param([long]$Value)
    if ($Value -ge 1GB) { return "{0:N2} GB" -f ($Value / 1GB) }
    if ($Value -ge 1MB) { return "{0:N2} MB" -f ($Value / 1MB) }
    if ($Value -ge 1KB) { return "{0:N2} KB" -f ($Value / 1KB) }
    return "$Value B"
}

$frame = 0
while ($true) {
    # Clear-Host только в бесконечном режиме на экране.
    if ($Count -eq 0) { Clear-Host }

    $frame++
    $now = Get-Date -Format "yyyy-MM-dd HH:mm:ss"

    $byCpu = @(Get-Process | Sort-Object CPU -Descending | Select-Object -First 5)
    $byMem = @(Get-Process | Sort-Object WorkingSet64 -Descending | Select-Object -First 5)

    Write-Host "============================================================"
    Write-Host " МОНИТОР ПРОЦЕССОВ - ТОП-5"
    Write-Host "============================================================"
    Write-Host " Время:   $now"
    Write-Host " Интервал: $Interval с   Кадр: $frame"
    Write-Host "============================================================"
    Write-Host ""
    Write-Host " ТОП-5 ПО ЗАГРУЗКЕ ПРОЦЕССОРА"
    Write-Host (" {0,-24} {1,12} {2,14}" -f "ИМЯ ПРОЦЕССА", "CPU (с)", "ПАМЯТЬ")
    Write-Host ("-" * 52)
    foreach ($p in $byCpu) {
        $cpu = if ($null -ne $p.CPU) { [math]::Round($p.CPU, 1) } else { 0 }
        Write-Host (" {0,-24} {1,12} {2,14}" -f $p.ProcessName, $cpu, (Format-Dep $p.WorkingSet64))
    }

    Write-Host ""
    Write-Host " ТОП-5 ПО ИСПОЛЬЗОВАНИЮ ПАМЯТИ"
    Write-Host (" {0,-24} {1,14} {2,12}" -f "ИМЯ ПРОЦЕССА", "ПАМЯТЬ", "CPU (с)")
    Write-Host ("-" * 52)
    foreach ($p in $byMem) {
        $cpu = if ($null -ne $p.CPU) { [math]::Round($p.CPU, 1) } else { 0 }
        Write-Host (" {0,-24} {1,14} {2,12}" -f $p.ProcessName, (Format-Dep $p.WorkingSet64), $cpu)
    }
    Write-Host ""

    if ($Count -gt 0 -and $frame -ge $Count) { break }
    Start-Sleep -Seconds $Interval
}

Write-Host "Монитор остановлен: выведено кадров - $frame"
